function neon(){
  return async function sql(strings,...vals){
    const q = strings.join('?').replace(/\s+/g,' ').trim();
    if (/SELECT COUNT\(\*\)::int AS count FROM "user"/i.test(q)) return [{count:0}];
    if (/SELECT id,username,password FROM "user"/i.test(q)) return [{id:1,username:'kujang642',password:'bad'}];
    if (/INSERT INTO "user"/i.test(q)) return [];
    if (/INSERT INTO user_sessions/i.test(q)) return [];
    return [];
  }
}
module.exports={neon};
